changeSet.sql:
-- 1. Переносим данные из старой таблицы в новую (сохраняя id) INSERT INTO krrg_organisations (id, name, description, created_at, updated_at) SELECT id, name, description, created_at, updated_at FROM krrg_vacancy_owner_organisations ON CONFLICT (id) DO NOTHING;
-- 2. Удаляем FK, которые ссылаются на старую таблицу DO $$ DECLARE r RECORD; BEGIN FOR r IN SELECT conname, conrelid::regclass AS tbl FROM pg_constraint WHERE confrelid = 'krrg_vacancy_owner_organisations'::regclass AND contype = 'f' LOOP EXECUTE format('ALTER TABLE %s DROP CONSTRAINT IF EXISTS %I', r.tbl, r.conname); END LOOP; END $$;
-- 3. Удаляем битые ссылки (если owner_organisation_id нет в krrg_organisations) DELETE FROM krrg_vacancies WHERE owner_organisation_id IS NOT NULL AND owner_organisation_id NOT IN (SELECT id FROM krrg_organisations);
-- 4. Создаём FK на krrg_organisations, если его ещё нет DO $$ BEGIN IF NOT EXISTS ( SELECT 1 FROM pg_constraint WHERE conname = 'fk_vacancies__owner_organisation' ) THEN ALTER TABLE krrg_vacancies ADD CONSTRAINT fk_vacancies__owner_organisation FOREIGN KEY (owner_organisation_id) REFERENCES krrg_organisations(id); END IF; END $$;
-- 5. Удаляем старую таблицу DROP TABLE IF EXISTS krrg_vacancy_owner_organisations;
